/**
 * DBCP-180 - verify that a GC can clean up an unused Statement when it is
 * no longer referenced even when it is tracked via the AbandonedTrace
 * mechanism.
 */
@Test
public void testGarbageCollectorCleanUp01() throws Exception {
    final DelegatingConnection<?> conn = (DelegatingConnection<?>) ds.getConnection();
    Assertions.assertEquals(0, conn.getTrace().size());
    createStatement(conn);
    Assertions.assertEquals(1, conn.getTrace().size());
    System.gc();
    Assertions.assertEquals(0, conn.getTrace().size());
}

/**
 * DBCP-180 - things get more interesting with statement pooling.
 */
@Test
public void testGarbageCollectorCleanUp02() throws Exception {
    ds.setPoolPreparedStatements(true);
    ds.setAccessToUnderlyingConnectionAllowed(true);
    final DelegatingConnection<?> conn = (DelegatingConnection<?>) ds.getConnection();
    final PoolableConnection poolableConn = (PoolableConnection) conn.getDelegate();
    final PoolingConnection poolingConn = (PoolingConnection) poolableConn.getDelegate();
    @SuppressWarnings("unchecked")
    final GenericKeyedObjectPool<PStmtKey, DelegatingPreparedStatement> gkop = (GenericKeyedObjectPool<PStmtKey, DelegatingPreparedStatement>) TesterUtils.getField(poolingConn, "pstmtPool");
    Assertions.assertEquals(0, conn.getTrace().size());
    Assertions.assertEquals(0, gkop.getNumActive());
    createStatement(conn);
    Assertions.assertEquals(1, conn.getTrace().size());
    Assertions.assertEquals(1, gkop.getNumActive());
    System.gc();
    // Finalization happens in a separate thread. Give the test time for
    // that to complete.
    int count = 0;
    while (count < 50 && gkop.getNumActive() > 0) {
        Thread.sleep(100);
        count++;
    }
    Assertions.assertEquals(0, gkop.getNumActive());
    Assertions.assertEquals(0, conn.getTrace().size());
}

@Test
public void testClose() throws Exception {
    ds.setAccessToUnderlyingConnectionAllowed(true);
    // active connection is held open when ds is closed
    final Connection activeConnection = getConnection();
    final Connection rawActiveConnection = ((DelegatingConnection<?>) activeConnection).getInnermostDelegate();
    assertFalse(activeConnection.isClosed());
    assertFalse(rawActiveConnection.isClosed());
    // idle connection is in pool but closed
    final Connection idleConnection = getConnection();
    final Connection rawIdleConnection = ((DelegatingConnection<?>) idleConnection).getInnermostDelegate();
    assertFalse(idleConnection.isClosed());
    assertFalse(rawIdleConnection.isClosed());
    // idle wrapper should be closed but raw connection should be open
    idleConnection.close();
    assertTrue(idleConnection.isClosed());
    assertFalse(rawIdleConnection.isClosed());
    ds.close();
    // raw idle connection should now be closed
    assertTrue(rawIdleConnection.isClosed());
    // active connection should still be open
    assertFalse(activeConnection.isClosed());
    assertFalse(rawActiveConnection.isClosed());
    // now close the active connection
    activeConnection.close();
    // both wrapper and raw active connection should be closed
    assertTrue(activeConnection.isClosed());
    assertTrue(rawActiveConnection.isClosed());
    // Verify SQLException on getConnection after close
    try {
        getConnection();
        fail("Expecting SQLException");
    } catch (final SQLException ex) {
        // Expected
    }
    // Redundant close is OK
    ds.close();
}

